import {latest, records, countries, types, countryName, recordPath, filterRecords} from './catalog.js';
import {glossaryTerms, annotateAcronyms, termsInText} from './glossary.js';
export const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repo = 'https://github.com/Yamans86/anticipatory-action';
const nav = [['/','Home'],['/framework','Framework'],['/why','Why this matters'],['/evidence','Evidence'],['/countries/CA','Canada Lab'],['/early-warning','Early Warning'],['/actions','Actions'],['/project','Project']];
const arrow = '<svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 12h16m-7-7 7 7-7 7"/></svg>';
export function layout(title, content, path) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-first research on AI-related labour-market change and anticipatory action. Canada pilot; transparent sources, methods and limitations."><title>${esc(title)} | Anticipatory Action</title><link rel="stylesheet" href="/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/">Anticipatory Action<span>Research platform</span></a><nav aria-label="Main navigation">${nav.map(([href,label])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${label}</a>`).join('')}</nav></header><main id="main">${annotateAcronyms(content)}</main><footer><span>Version 0.5.0 · Core anticipatory-action framework</span><div><a href="/glossary">Glossary</a><a href="/methodology">Methodology</a><a href="${repo}">Source code</a><a href="/api/catalog.json">Download catalog</a></div></footer></body></html>`;
}
const intro = (title,desc) => `<div class="intro"><h1>${esc(title)}</h1><p class="lead">${esc(desc)}</p></div>`;
const notice = '<div class="notice">Research in development. No operational trigger is active, and no population is treated as vulnerable by status alone.</div>';
const row = (href,title,desc) => `<a class="editorial-row" href="${href}"><h3>${esc(title)}</h3><span>${esc(desc)}</span>${arrow}</a>`;

const frameworkFlow = () => {
  const steps = [
    ['1','Technological hazard','Artificial intelligence adoption, task automation and changing hiring patterns.'],
    ['2','Occupational pressure','Vacancies, hours, wages or job design begin to weaken or change.'],
    ['3','Exposure','Identify workers concentrated in affected occupations and tasks.'],
    ['4','Vulnerability','Ask who has the least financial, legal, social or skills capacity to absorb the shock.'],
    ['5','Protection gap','Compare transition needs with savings, benefits, employer support and public protection.'],
    ['6','Trigger','Act when evidence and vulnerability conditions cross a pre-agreed decision rule.'],
    ['7','Action package','Deliver support early enough to preserve income, resilience and transition options.'],
    ['8','Outcome','Aim for sustainable employment transitions and lower household and public costs.']
  ];
  return `<section class="framework-flow" aria-labelledby="framework-flow-title"><div class="section-head"><p class="label">Core pathway</p><h2 id="framework-flow-title">From technological disruption to anticipatory action</h2><p>Each step must be evidenced separately. Exposure is not impact, migration status is not vulnerability, and a labour-market signal is not automatically an artificial-intelligence effect.</p></div><ol class="flow-steps">${steps.map(([n,t,d])=>`<li><span class="step-no">${n}</span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol><p class="visual-note"><strong>Core idea:</strong> fragility does not have to describe the country. It can describe a household's ability to absorb and recover from a shock.</p></section>`;
};

const humanitarianBridge = () => `<section class="bridge" aria-labelledby="bridge-title"><div class="section-head"><p class="label">Where the idea comes from</p><h2 id="bridge-title">Humanitarian anticipatory action, extended to technological shocks</h2></div><div class="bridge-grid"><article><h3>Traditional humanitarian anticipatory action</h3><p>Monitor a forecastable hazard, understand exposure and vulnerability, agree triggers, and act before the predicted impact becomes a humanitarian crisis.</p><div class="mini-chain" aria-label="Traditional anticipatory action sequence"><span>Hazard</span><b>→</b><span>Exposure</span><b>→</b><span>Vulnerability</span><b>→</b><span>Trigger</span><b>→</b><span>Early action</span></div></article><div class="bridge-arrow" aria-hidden="true">→</div><article><h3>This project</h3><p>Apply the same logic to labour-market disruption in advanced economies, where national institutions may be strong but individual households can still have very limited shock-absorption capacity.</p><div class="mini-chain" aria-label="Technology disruption anticipatory action sequence"><span>AI-related pressure</span><b>→</b><span>Workers exposed</span><b>→</b><span>Household fragility</span><b>→</b><span>Trigger</span><b>→</b><span>Transition support</span></div></article></div></section>`;

const vulnerabilityMatrix = () => `<section class="vulnerability-section" aria-labelledby="vulnerability-title"><div class="section-head"><p class="label">Targeting principle</p><h2 id="vulnerability-title">Who may need anticipatory support?</h2><p>The unit of analysis is vulnerability to the shock, not nationality. Refugees, asylum seekers, migrants and temporary workers matter because some may face several constraints at once, but economically vulnerable citizens can face the same or greater risk.</p></div><div class="matrix-layout"><div class="matrix" role="img" aria-label="Matrix of exposure to labour disruption versus adaptive capacity and resilience"><div class="matrix-y">Higher exposure ↑</div><article class="quad priority"><h3>Priority for anticipatory action</h3><p>Higher exposure + weaker resilience + weaker protection</p><small>Examples can include refugees, asylum seekers, recent migrants, temporary workers, low-income citizens, precarious workers, single-parent households, older workers in declining occupations, people with disabilities and highly indebted households.</small></article><article class="quad manage"><h3>Manage transition</h3><p>Higher exposure + stronger savings, skills, mobility or protection.</p></article><article class="quad lower"><h3>Lower immediate risk</h3><p>Lower exposure + stronger buffers.</p></article><article class="quad watch"><h3>Watch inequality and exclusion</h3><p>Lower exposure today does not remove structural barriers or future risk.</p></article><div class="matrix-x">Adaptive capacity and resilience →</div></div><aside class="vulnerability-factors"><h3>What can increase vulnerability?</h3><ul><li>Low liquid savings</li><li>High housing costs or debt</li><li>Benefit ineligibility or short coverage</li><li>Credential-recognition barriers</li><li>Language barriers</li><li>Weak social networks</li><li>Care responsibilities</li><li>Restricted geographic or legal mobility</li><li>Long retraining requirements</li><li>Jobs being phased out faster than workers can transition</li></ul></aside></div><p class="visual-note"><strong>Important:</strong> migration status can shape access to work, benefits and mobility, but it is not itself a vulnerability score.</p></section>`;

const riskEquation = () => `<section class="risk-equation" aria-labelledby="risk-title"><div class="section-head"><p class="label">Working risk logic</p><h2 id="risk-title">Risk rises when exposure meets low resilience and weak protection</h2></div><div class="equation-row"><div><strong>Labour-market exposure</strong><span>How much the person's occupation or tasks are under pressure</span></div><b>×</b><div><strong>Household vulnerability</strong><span>Income, savings, debt, housing and care obligations</span></div><b>×</b><div><strong>Low adaptive capacity</strong><span>Skills transferability, credentials, language, mobility and networks</span></div><b>×</b><div><strong>Protection gaps</strong><span>Eligibility, benefit duration, employer support and policy coverage</span></div></div><p>This is a conceptual framework, not a validated multiplicative score. The research tests each component before any trigger can be operational.</p></section>`;

const actionTimeline = () => {
  const stages = [
    ['Readiness','Monitoring systems','Pre-agreed trigger rules','Employer and training partnerships','Target-population mapping'],
    ['Early pressure','Targeted information','Career and skills assessment','Credential support','Financial and transition planning'],
    ['Likely phase-out','Paid retraining','Reduced-hours arrangements','Retention subsidies','Employer transition agreements'],
    ['Imminent displacement','Temporary income top-ups','Rent and utility protection','Childcare support','Transport and mobility grants'],
    ['Transition and recovery','Job matching','Wage insurance','Apprenticeships','Relocation support','Tapered exit']
  ];
  return `<section class="action-timeline" aria-labelledby="action-timeline-title"><div class="section-head"><p class="label">Candidate activity catalogue</p><h2 id="action-timeline-title">What anticipatory action could look like across the transition</h2><p>These are candidate packages for testing, not approved programmes. The point is to define actions before the trigger, so institutions are not designing support after harm has already occurred.</p></div><ol>${stages.map((stage,i)=>`<li><span class="stage-no">${i+1}</span><h3>${stage[0]}</h3><ul>${stage.slice(1).map(x=>`<li>${x}</li>`).join('')}</ul></li>`).join('')}</ol><div class="systemic-band"><h3>If disruption becomes large-scale</h3><p>Broader mechanisms may need to be analysed alongside targeted support: expanded unemployment protection, guaranteed minimum income, negative income tax, universal basic services, transition-income guarantees or universal/basic-income models. The project should compare these options rather than assume one answer.</p></div></section>`;
};

const transitionGap = () => `<section class="transition-gap" aria-labelledby="transition-gap-title"><div class="section-head"><p class="label">Why timing matters</p><h2 id="transition-gap-title">A household can live in a wealthy country and still run out of time</h2></div><div class="gap-bars"><div><span>Warning lead time</span><i style="--w:24%"></i></div><div><span>Liquid financial runway</span><i style="--w:18%"></i></div><div><span>Income protection</span><i style="--w:30%"></i></div><div class="need"><span>Time needed for sustainable transition</span><i style="--w:86%"></i></div></div><p>The research question is whether warning time + household runway + policy protection is long enough to cover the transition. The proportions above are schematic, not measured Canadian values.</p></section>`;

const costLogic = () => `<section class="cost-logic" aria-labelledby="cost-title"><div class="section-head"><p class="label">Economic case</p><h2 id="cost-title">Compare the cost of acting early with the cost of waiting</h2></div><div class="cost-columns"><article><h3>Anticipatory investment</h3><ul><li>Paid retraining and credential conversion</li><li>Temporary income support</li><li>Childcare and mobility support</li><li>Retention or reduced-hours mechanisms</li><li>Job matching and transition services</li></ul></article><article><h3>Potential cost of delayed action</h3><ul><li>Longer unemployment and larger benefit claims</li><li>Housing and debt distress</li><li>Lost tax revenue and labour participation</li><li>Higher social-service demand</li><li>Longer-term poverty and exclusion risks</li></ul></article></div><p>The future costing model should test whether an earlier transition package reduces expected household and public costs compared with reactive support alone.</p></section>`;
export function home() {
  return `<section class="hero core-hero"><div><p class="label">A humanitarian idea for a new kind of shock</p><h1>Anticipatory action for technological disruption.</h1><p class="lead">This project adapts humanitarian early-warning and anticipatory-action logic to emerging socioeconomic fragility inside advanced economies.</p><p>Strong national institutions do not mean every household can absorb a fast labour-market shock. The question is whether we can identify pressure early, understand who has the least resilience, and act before job disruption becomes household crisis.</p><div class="hero-links"><a href="/framework">Understand the framework ${arrow}</a><a href="/countries/CA">See the Canada pilot ${arrow}</a></div></div><aside class="hero-thesis"><p class="label">Core proposition</p><blockquote>Fragility can exist inside a strong society. Anticipatory action should focus on the household's ability to absorb, adapt to and recover from a shock.</blockquote><p>Refugees, asylum seekers, migrants and temporary workers are priority populations to study because protection, mobility, credentials and savings can intersect. They are not assumed vulnerable by status alone.</p></aside></section>${notice}${humanitarianBridge()}${frameworkFlow()}${vulnerabilityMatrix()}${transitionGap()}<section class="question"><div><p class="label">First empirical laboratory</p><h2>Canada tests whether this humanitarian logic can be translated into measurable labour-market, household-resilience and policy-protection indicators.</h2></div><div><p class="label">What comes after evidence</p><h2>Pre-agreed triggers, costed activity packages and accountable exit conditions.</h2></div></section><section aria-label="Explore the research">${row('/framework','Core framework','See the full theory of change, vulnerability logic, transition gap and cost case.')}${row('/countries/CA','Canada Lab','Inspect the first empirical test of the framework.')}${row('/early-warning','Early warning','See how hazard, exposure, vulnerability and protection gaps become a decision trigger.')}${row('/actions','Anticipatory actions','Explore candidate activities before, during and after labour-market disruption.')}${row('/evidence','Evidence and data','Follow every source, dataset, limitation and dependency.')}${row('/project','Project history','See how the humanitarian concept became an open research platform.')}</section>`;
}

function table(items) {
  if (!items.length) return '<p class="empty" role="status">No records match these filters. Try a broader search or reset the filters.</p>';
  return `<div class="table-scroll"><table><caption class="sr-only">Research records</caption><thead><tr><th scope="col">Record</th><th scope="col">Type</th><th scope="col">Country</th><th scope="col">Status</th></tr></thead><tbody>${items.map(r=>{const titleTerms=termsInText(r.title);return `<tr><td><a href="${recordPath(r)}">${esc(r.title)}</a><small>${r.id} · v${r.version}</small>${titleTerms.length?`<small class="title-expansion">${titleTerms.map(x=>`${esc(x.full)} (${esc(x.abbr)})`).join(' · ')}</small>`:''}</td><td class="capitalize">${r.type}</td><td>${countryName(r.country)}</td><td class="capitalize">${r.status}</td></tr>`}).join('')}</tbody></table></div>`;
}
export function catalog(url, allowed = types, title='Research catalog', desc='Follow each research object and its evidence chain.') {
  const q=url.searchParams.get('q')||'', type=url.searchParams.get('type')||'', country=url.searchParams.get('country')||'';
  const items=filterRecords({q,type,country},latest.filter(r=>allowed.includes(r.type)));
  return `${intro(title,desc)}<form class="filters" method="get"><label>Search records<input name="q" value="${esc(q)}" placeholder="Search by title, keyword or ID…" maxlength="200"></label><label>Type<select name="type"><option value="">All types</option>${allowed.map(t=>`<option value="${t}" ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label>Country<select name="country"><option value="">All countries</option>${countries.map(c=>`<option value="${c.code}" ${c.code===country?'selected':''}>${c.name}</option>`).join('')}</select></label><button>Filter</button></form><div class="result-meta"><span>${items.length} record${items.length===1?'':'s'}</span><a href="${esc(url.pathname)}">Reset filters</a></div>${table(items)}<section class="prose"><h2>What a record tells you</h2><p>Every record carries a permanent ID, version, provenance, limitations and links to related research. A link shows a dependency or proposed use; it does not imply that the evidence has validated the downstream object.</p><p><a href="/catalog">Browse all research objects</a> · <a href="/api/catalog.json">Download the versioned catalog</a></p></section>`;
}
export function detail(r) {
  const dependents=records.filter(x=>x.links.some(l=>l.id===r.id&&l.version===r.version));
  const links=rs=>rs.length?`<ul>${rs.map(x=>`<li><a href="${recordPath(x)}">${esc(x.title)}</a> <small>v${x.version}</small></li>`).join('')}</ul>`:'<p>None recorded in this release.</p>';
  const termsUsed=termsInText(JSON.stringify(r));
  const terminology=termsUsed.length?`<dl>${termsUsed.map(x=>`<dt>${esc(x.full)} (${esc(x.abbr)})</dt><dd>${esc(x.meaning)}</dd>`).join('')}</dl><p><a href="/glossary">Open the full glossary</a></p>`:'<p>No specialist abbreviations are used in this record.</p>';
  return `<p class="breadcrumb"><a href="/catalog">Research catalog</a> / ${esc(r.type)}</p>${intro(r.title,r.summary)}<div class="detail-layout"><article class="prose"><h2>Purpose</h2><p>${esc(r.body)}</p><h2>Limitations</h2><ul>${r.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul><h2>Specification</h2><dl>${Object.entries(r.details).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h2>Evidence and dependencies</h2>${r.links.length?`<ul>${r.links.map(l=>`<li>${esc(l.relation)}: <a href="/objects/${l.id}/v/${l.version}">${l.id} · v${l.version}</a></li>`).join('')}</ul>`:'<p>No upstream research objects recorded.</p>'}<h2>Used by</h2>${links(dependents)}<h2>Terms used on this page</h2>${terminology}<h2>Provenance</h2><dl>${Object.entries(r.provenance).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${k==='url'&&v?`<a href="${esc(v)}">Publisher source</a>`:esc(v??'Not available — no executed data or code artifact')}</dd>`).join('')}</dl></article><aside aria-label="Record metadata"><dl><dt>Permanent ID</dt><dd><code>${r.id}</code></dd><dt>Version</dt><dd>${r.version}</dd><dt>Status</dt><dd class="capitalize">${r.status}</dd><dt>Country</dt><dd>${countryName(r.country)}</dd><dt>Updated</dt><dd>${r.updated}</dd></dl><p><a href="${recordPath(r)}">Version permalink</a></p><p><a href="/api/objects/${r.id}/v/${r.version}.json">Download record JSON</a></p><p><a href="${repo}/commits/main/content/records.json">Editorial history</a></p><h3>Available versions</h3>${links(records.filter(x=>x.id===r.id))}</aside></div>`;
}
export function countryPage(c) {
  const canada = c.code === 'CA' ? `<section class="prose"><h2>What the Canada Lab has already done</h2><p>The Canada work has moved beyond scoping. A computational proof of concept tested five linked questions using Canadian public evidence, negative controls, coverage checks, policy rules and transition-time sensitivity tests: occupational transition pressure, population exposure, household vulnerability and adaptive capacity, policy protection gaps, and whether workers have enough protected time to transition.</p><p><strong>Current proof-of-concept verdict:</strong> the quantitative architecture survives, but calibration is not production-ready. The broad structural artificial-intelligence displacement alarm was <strong>not triggered</strong>. That is a useful result: the model can distinguish high AI exposure and adoption from demonstrated labour displacement.</p><p>The validation also produced failures and downgrades that remain public. The top-10 non-permanent-resident occupational slice cannot rank whole populations; Financial Runway is source-feasible but not yet estimated; Work-Sharing has an unresolved artificial-intelligence shock-fit question; and the Protected Transition Margin and Timely Transition Probability mechanics work but transition-time calibration is still too uncertain for operational thresholds.</p><p><a href="/canada-poc">Computational proof of concept and validation</a> · <a href="/canada-data">Data architecture</a> · <a href="/experiments">Experiments</a> · <a href="/actions">Policy and action options</a></p></section>` : `<section class="prose"><h2>Research status: ${esc(c.stage)}</h2><p>Country membership does not imply that an indicator is comparable across borders. Every lab requires local definitions, sources, validation and action logic.</p></section>`;
  return `${intro(`${c.name} Lab`,c.description)}${notice}${canada}<section class="prose"><h2>Research objects</h2><p>Each item below is versioned and keeps its own limitations, provenance and evidence dependencies.</p></section>${table(latest.filter(r=>r.country===c.code))}`;
}
const prose = body => `<article class="prose wide">${body}</article>`;

const canadaPoc = () => intro('Canada computational proof of concept','The architecture survived validation. The current broad structural artificial-intelligence displacement alarm did not trigger. Calibration is not production-ready.')+notice+prose('<p class="language-note"><strong>How to read this page:</strong> every model is written out before its abbreviation. Any shorthand used later on the site also has a definition and appears in the <a href="/glossary">glossary</a>.</p><h2>What we tested</h2><ol><li><strong>Occupational Transition Pressure Model (OTPM):</strong> tests whether artificial intelligence exposure and observed use are accompanied by unusual labour-market deterioration.</li><li><strong>Population Exposure Model (PEXM):</strong> identifies which population groups are concentrated in occupational pathways under pressure.</li><li><strong>Vulnerability and Adaptive Capacity Model (VACM):</strong> assesses how much capacity households have to absorb an income shock and adapt.</li><li><strong>Policy Buffer and Protection Gap Model (PBGM):</strong> measures how much protection existing programmes provide and where gaps remain.</li><li><strong>Transition Velocity and Protected Transition Margin Model (TVPM):</strong> tests whether warning time plus protected income creates enough time for a sustainable employment transition.</li></ol><p><strong>Overall v0.2 verdict: SHARE WITH CAVEATS.</strong> The architecture is retained, but the calibration is not ready for operational use.</p><h2>Validation gate</h2><div class="table-scroll"><table><thead><tr><th>Component</th><th>Status</th><th>Finding</th></tr></thead><tbody><tr><td>OTPM · exposure vs deployment</td><td>PASS</td><td>Observed GenAI use differs strongly across C-AIOE groups.</td></tr><tr><td>OTPM · labour deterioration</td><td>PASS</td><td>HELC vacancy decline was not differential from low-exposure decline; broad employment grew.</td></tr><tr><td>OTPM · AI attribution</td><td>PASS / REQUIRED</td><td>COVID and baseline tests show labour change alone is non-specific.</td></tr><tr><td>OTPM · current structural alarm</td><td>NOT TRIGGERED</td><td>Evidence supports monitoring, not a structural-displacement declaration.</td></tr><tr><td>PEXM · population heterogeneity</td><td>PASS</td><td>Published NPR occupational structures materially differ.</td></tr><tr><td>PEXM · top-10 exposure ranking</td><td>FAIL / DOWNGRADED</td><td>Uncovered-share uncertainty bounds overlap strongly.</td></tr><tr><td>PEXM · full detailed matrix</td><td>SOURCE READY</td><td>Detailed occupation-by-admission-category data exist; ingestion is pending.</td></tr><tr><td>VACM · runway source feasibility</td><td>PASS</td><td>SFS, SHS and MBM provide the required source families.</td></tr><tr><td>VACM · actual liquid runway</td><td>NOT VALIDATED</td><td>Microdata have not yet been ingested and linked.</td></tr><tr><td>PBGM · rule encoding</td><td>PASS</td><td>EI, Work-Sharing and Worker Retention Grant parameters can be represented.</td></tr><tr><td>PBGM · AI shock fit</td><td>OPEN</td><td>Efficiency-driven staffing rules create a substantive programme-fit question.</td></tr><tr><td>TVPM · equation integrity</td><td>PASS</td><td>Lead time, protection and transition speed move TTP in the expected direction.</td></tr><tr><td>TVPM · calibration</td><td>NOT VALIDATED</td><td>Any-job unemployment duration is not sustainable-transition duration.</td></tr></tbody></table></div><h2>Occupational transition pressure (OTPM): deployment is real; displacement is not demonstrated</h2><p>In the proof of concept (POC), high-exposure, high-complementarity (HEHC) occupations represented 31.2% of the workforce and 53.8% of workers reported generative-artificial-intelligence use. High-exposure, low-complementarity (HELC) occupations represented 29.6% of the workforce with 45.9% reported use. Low-exposure (LE) occupations represented 39.3% with 14.2% reported use.</p><p>HELC vacancies fell by roughly 50% from 2022Q4 to 2025Q3, but low-exposure vacancies also fell by roughly 50%. That produces approximately zero relative vacancy deterioration in this comparison. The POC therefore remains at <strong>Active deployment/watch</strong>, not structural transition.</p><h2>Negative control: labour reallocation is not automatically artificial-intelligence causation</h2><div class="table-scroll"><table><thead><tr><th>Window</th><th>AI period</th><th>COVID</th><th>Baseline</th></tr></thead><tbody><tr><td>3 months</td><td>2.7</td><td>4.3</td><td>2.8</td></tr><tr><td>6 months</td><td>4.8</td><td>5.9</td><td>4.7</td></tr><tr><td>12 months</td><td>6.1</td><td>6.7</td><td>6.1</td></tr><tr><td>24 months</td><td>7.0</td><td>6.9</td><td>6.6</td></tr></tbody></table></div><p>COVID occupational reallocation moved faster at short horizons. Over longer windows the AI-period pattern was broadly similar to the baseline. That is why AI attribution remains a separate confidence layer instead of being inferred from labour movement alone.</p><h2>Population exposure (PEXM): migrant and non-permanent-resident groups cannot be collapsed into one population</h2><p>The top-10 occupation slice covered 41.8% of asylum claimants, 39.2% of people with work-and-study permits, 54.7% of study-permit-only workers, 25.0% of work-permit-only workers and 23.1% of other non-permanent-resident (NPR) types. The groups clearly have different occupational structures, but the uncovered shares are too large for a defensible whole-population ranking.</p><p>The earlier directional claim that work-permit-only workers were more exposed than asylum claimants was therefore withdrawn as a full-population conclusion. The next step is the complete population × occupation matrix.</p><h2>Vulnerability and adaptive capacity (VACM): financial fragility is real, but Financial Runway is not yet measured</h2><p>The earlier POC found a substantial difference in the pooled income-wealth evidence: 45.9% of recent immigrant families fell in the lower-wealth quartile across the three income bands used, compared with 18.3% of established immigrant families and 22.8% of Canadian-born families. This supports the need for a fragility layer, but it does not provide liquid Financial Runway.</p><p>v0.2 established that the required source families exist: the Survey of Financial Security (SFS) for assets, debts and income; the Survey of Household Spending (SHS) for household expenditure; and the Market Basket Measure (MBM) for a minimum-needs floor. The remaining problem is microdata engineering and defensible linkage to population and occupation.</p><h2>Policy buffers and protection gaps (PBGM): rules can be encoded, but programme fit matters</h2><div class="table-scroll"><table><thead><tr><th>Programme</th><th>Role in POC</th><th>Approx. replacement represented</th><th>Timing</th></tr></thead><tbody><tr><td>Employment Insurance (EI) regular</td><td>Post-layoff income baseline</td><td>55%</td><td>Reactive</td></tr><tr><td>Work-Sharing</td><td>Pre-layoff retention</td><td>55% of reduced income</td><td>26 weeks + possible extension</td></tr><tr><td>Worker Retention Grant</td><td>Retention + training</td><td>70% of lost income</td><td>Linked to Work-Sharing</td></tr></tbody></table></div><p>The model can represent eligibility, latency, replacement and duration. The unresolved issue is a <strong>Shock-Fit Gap</strong>: a mathematically useful mechanism may still fail statutory or programme rules for a specific AI-enabled restructuring.</p><h2>Transition timing and protected margin (TVPM): the mechanics work; the calibration does not yet</h2><p>The Transition Velocity and Protected Transition Margin Model (TVPM) uses two candidate measures: Protected Transition Margin (PTM), which compares available protected time with the time required for transition, and Timely Transition Probability (TTP), which estimates the probability of completing a transition within the effective warning and protection window. All monotonicity assertions passed: more warning time and more protected runway increase Timely Transition Probability, while slower transition assumptions reduce it.</p><div class="table-scroll"><table><thead><tr><th>Protected runway</th><th>0-week lead</th><th>6-week lead</th><th>12-week lead</th></tr></thead><tbody><tr><td>6 weeks</td><td>0.7%</td><td>11.2%</td><td>31.6%</td></tr><tr><td>14 weeks</td><td>17.5%</td><td>38.7%</td><td>57.6%</td></tr><tr><td>26 weeks</td><td>57.6%</td><td>71.6%</td><td>81.1%</td></tr><tr><td>38 weeks</td><td>81.1%</td><td>87.4%</td><td>91.6%</td></tr><tr><td>45 weeks</td><td>88.2%</td><td>92.1%</td><td>94.7%</td></tr></tbody></table></div><p>These are scenario mechanics, not estimates of programme effectiveness. At a fixed 32-week window, Timely Transition Probability (TTP) ranged from 83.5% to 38.7% as the assumed sustainable-transition duration increased. No operational threshold should be frozen until pathway-specific transition durations are estimated.</p><h2>What comes next</h2><ol><li>Ingest the full Population Exposure Model (PEXM) occupation matrix with suppression and coverage metadata.</li><li>Build Financial Runway from Survey of Financial Security (SFS), Survey of Household Spending (SHS) and Market Basket Measure (MBM) inputs with explicit synthetic-linkage uncertainty where needed.</li><li>Estimate time to any job and time to sustainable employment separately, including credentials and training.</li><li>Encode policy eligibility and realized take-up, including temporary-worker scenarios.</li><li>Run additional historical negative controls and sectoral contractions while keeping AI attribution separate.</li></ol><p><strong>Next quantitative gate:</strong> Canada Quantitative Engine v1.0 - data ingestion + calibration.</p><p><a href="/objects/AA-EXP-CA-004/v/0.2.0">Open the versioned v0.2 validation record</a> · <a href="/canada-data">Canada data architecture</a> · <a href="https://github.com/Yamans86/anticipatory-action/blob/main/docs/canada-poc-v0.2.md">Technical validation summary</a></p>');

const glossaryPage = () => {
  const items=glossaryTerms.map(x=>`<section id="term-${esc(x.abbr)}"><h2>${esc(x.full)} <small>(${esc(x.abbr)})</small></h2><p>${esc(x.meaning)}</p></section>`).join('');
  return intro('Glossary','Plain-English definitions for the research models, datasets, measures and technical shorthand used on this site.')+prose(`<p>This project uses abbreviations because some model and dataset names are long. The rule is simple: <strong>the full name comes first, the abbreviation comes second</strong>. Abbreviations elsewhere on the site also carry their definition.</p><div class="glossary">${items}</div><h2>Writing standard</h2><p>New public-facing research should not introduce an unexplained acronym. If a term is useful enough to keep, it must be written out on first use and added to this glossary. Internal shorthand should stay internal.</p>`);
};
export const staticPages = {
  '/framework':['Framework',()=>intro('The anticipatory-action framework','A humanitarian approach to early action, adapted to technological and labour-market shocks in advanced economies.')+humanitarianBridge()+frameworkFlow()+riskEquation()+vulnerabilityMatrix()+transitionGap()+costLogic()+actionTimeline()+prose('<h2>What this framework is trying to prevent</h2><p>The objective is not to predict every job loss. It is to identify credible pressure early enough that households with low shock-absorption capacity have a realistic path to sustainable employment before savings, benefits and social protection are exhausted.</p><h2>What makes an action anticipatory</h2><p>An action is anticipatory only when it is linked to a forecast or signal, delivered before the worst expected impact, targeted using evidence on exposure and vulnerability, and governed by pre-agreed rules. Ordinary reactive benefits remain important but answer a different question.</p><p><a href="/early-warning">How triggers would work</a> · <a href="/actions">Candidate action packages</a> · <a href="/countries/CA">Canada as the first test case</a></p>')],
  '/canada-poc':['Canada computational proof of concept',canadaPoc],
  '/glossary':['Glossary',glossaryPage],
  '/why': ['Why this matters',()=>intro('Fragility can exist inside strong societies','Advanced economies may have strong institutions while some households have very little capacity to absorb a fast labour-market shock.')+humanitarianBridge()+riskEquation()+vulnerabilityMatrix()+costLogic()+prose('<h2>Why refugees, asylum seekers and migrants are central to the research</h2><p>The project does not assume that all migrants are vulnerable. It studies these groups because legal status, benefit eligibility, credential recognition, language, mobility, occupational concentration, family obligations and financial buffers can interact. Those same dimensions are also relevant to vulnerable citizens.</p><h2>The practical question</h2><p>If a worker is likely to need nine months for a sustainable transition, but savings and income protection cover only six months, the three-month gap matters. Anticipatory action asks whether support can be triggered before that gap becomes rent arrears, debt distress, food insecurity, homelessness or long-term labour-market exclusion.</p><h2>The public-policy question</h2><p>Can governments and institutions spend earlier and more intelligently on transition support rather than waiting to finance the downstream costs of unemployment and household distress? This project will eventually compare candidate actions by timing, coverage, cost, expected benefit and exit condition.</p>')],
  '/early-warning': ['Early Warning',()=>intro('Early warning for socioeconomic fragility','Translate humanitarian hazard → exposure → vulnerability → trigger logic into a labour-market setting.')+notice+frameworkFlow()+prose('<h2>What has to be true before a trigger can fire</h2><ol><li><strong>Pressure is credible:</strong> a labour-market change is unusual enough to investigate.</li><li><strong>Exposure is specific:</strong> occupations, tasks or groups facing the pressure are identified.</li><li><strong>Vulnerability is material:</strong> affected households have limited financial runway or adaptive capacity.</li><li><strong>Protection is insufficient:</strong> existing savings, employer support or public programmes leave a meaningful transition gap.</li><li><strong>An action exists:</strong> a feasible, costed response can plausibly improve the outcome if delivered now.</li><li><strong>A decision owner exists:</strong> someone is accountable for activation, review and stopping the action.</li></ol><h2>What a trigger is not</h2><p>A trigger is not a scary headline, a single artificial-intelligence exposure score or a prediction that a profession will disappear. It is a pre-agreed decision rule connecting evidence to an action.</p><h2>Current status</h2><p>No live trigger is active. Canada is being used to test the measurement chain before any operational threshold is proposed.</p>')+table(latest.filter(r=>r.type==='model'))],
  '/actions': ['Anticipatory actions',()=>intro('From early warning to an action package','The project will build and test a catalogue of activities that can be delivered before labour disruption becomes household crisis.')+notice+actionTimeline()+transitionGap()+costLogic()+prose('<h2>Every future activity needs an implementation contract</h2><p>A candidate activity is not ready for an anticipatory-action plan until it specifies: the trigger, target population, objective, lead actor, delivery mechanism, eligibility, timing, duration, indicative cost, evidence, implementation risks, safeguarding considerations and exit condition.</p><h2>Targeted support first, broader guarantees when scale changes</h2><p>Small or concentrated shocks may call for targeted retraining, retention, mobility or temporary income support. If disruption becomes broad and simultaneous, the research should compare larger safety-net options such as guaranteed minimum income, negative income tax, universal basic services, transition-income guarantees or universal basic income. The project does not assume in advance which mechanism is best.</p><h2>What success means</h2><p>The outcome is not merely “a person received assistance.” The intended result is a sustainable employment transition, preserved household resilience and lower expected social and fiscal cost than delayed response.</p>')+table(latest.filter(r=>r.type==='action'))],
  '/methodology':['Methodology',()=>intro('Make the reasoning inspectable','A result is only useful when its evidence, assumptions and limits travel with it.')+prose('<h2>Permanent identity and versions</h2><p>Objects retain a permanent ID even when their title changes. Version-specific links pin the exact record used. Published versions are retained; corrections create a new version and explain what changed. The unversioned object URL redirects to its latest version.</p><h2>Evidence is not a status shortcut</h2><p>Catalogued means a source has been described. Proposed, planned and concept records have not been validated. A dependency link records intended use, not proof. Validation requires a documented review and reproducible results.</p><h2>Reproducibility</h2><p>Executed work must identify original data releases, retrieval dates, licences, file checksums, transformation code commits, environment, parameters and run logs. This release includes metadata only; null artifact fields mean no analysis has been executed.</p><h2>Analysis and uncertainty</h2><p>Pre-specify outcomes and evaluation windows. Use time-aware splits, avoid future-information leakage, compare baselines and retain failed or null results. Distinguish causal claims from prediction. Report sampling error, revisions, missingness and subgroup limitations.</p><h2>Across countries</h2><p>Each record is attached to a country registry entry. Additional country labs use the same object types but retain local definitions, institutional context and source licences. Cross-country comparison requires an explicit harmonisation protocol.</p><h2>Plain-language writing standard</h2><p>Public pages write out a model, dataset or metric name before using its abbreviation. Any shorthand that remains must be defined in the <a href="/glossary">glossary</a>. Internal shorthand should not be treated as reader knowledge.</p><h2>Editorial workflow</h2><p>Propose changes in Git, add a versioned record, validate references and provenance, review the limitations and update the changelog. Existing published versions must not be edited or removed. The site is built from those records.</p><p><a href="/catalog">Inspect the catalog</a> · <a href="/project">Read project decisions</a></p>')],
  '/canada-data':['Canada data architecture',()=>intro('Canada data architecture','What we can measure now, what remains unresolved, and how vulnerability and AI exposure are kept separate.')+prose('<h2>Four evidence layers</h2><ol><li><strong>Vulnerability outcomes:</strong> monthly three-month-moving-average labour-force outcomes by immigrant status, age and gender.</li><li><strong>Occupation employment:</strong> monthly seasonally adjusted employment by occupation for broad high-frequency context.</li><li><strong>Labour demand:</strong> quarterly five-digit National Occupational Classification (NOC) job vacancies and offered wages, detailed enough for exposure-group analysis once the crosswalk is fixed.</li><li><strong>AI exposure and adoption:</strong> Statistics Canada Complementarity-Adjusted Artificial Intelligence Occupational Exposure (C-AIOE) research plus observed generative-artificial-intelligence use as a separate adoption check.</li></ol><h2>Initial vulnerability dimensions</h2><p>The first analytical segmentation is immigration recency, age, gender and geography where sample quality permits. Education is a priority secondary dimension. These are analytical dimensions, not vulnerability labels by themselves.</p><p><strong>Important boundary:</strong> the public monthly immigrant-status series does not identify refugees or asylum seekers. We will not treat immigrant status as a proxy for either group.</p><h2>Current data gap</h2><p>The detailed quarterly vacancy table can be mapped to AI-exposure groups at five-digit NOC level. The public monthly occupation-employment table may be too coarse to reproduce the same HELC grouping precisely. Until a defensible published grouped series, custom tabulation or microdata route is resolved, the monthly high-exposure, low-complementarity (HELC) employment input remains planned rather than fabricated.</p><h2>Two analytical tracks</h2><p>The restored <a href="/canada-poc">Canada computational POC</a> already executed the OTPM → PEXM → VACM → PBGM → TVPM architecture on a source-backed thin slice and validation pass. Separately, <a href="/objects/AA-EXP-CA-002/v/0.1.0">AA-EXP-CA-002</a> is the next-generation rolling-origin forecast protocol. Its code is implemented, but its production-grade real-data run remains pending versioned monthly inputs.</p><p><a href="https://github.com/Yamans86/anticipatory-action/tree/main/analysis/canada">View experiment code and input contract</a> · <a href="/evidence">Browse sources and datasets</a></p>')],
  '/project': ['Project',()=>intro('A humanitarian concept extended into a public research platform','The project asks whether anticipatory action can protect household resilience during technology-driven labour transitions in advanced economies.')+prose('<h2>How the project began</h2><p>Humanitarian anticipatory action normally focuses on fragile or crisis-affected communities: monitor a hazard, understand who is exposed and vulnerable, agree triggers, and act before the predicted impact becomes a humanitarian emergency.</p><p>This project starts from the proposition that technological change can create pockets of socioeconomic fragility inside advanced societies. A country may be wealthy and institutionally strong while a worker or household has little savings, weak benefit eligibility, difficult credentials, limited mobility or a long retraining path.</p><h2>Who the project is for</h2><p>The focus includes refugees, asylum seekers, migrants, temporary workers and other groups who may face compounded barriers, alongside low-income and otherwise economically vulnerable citizens. The targeting principle is vulnerability to the shock, not migration status itself.</p><h2>What the project must eventually produce</h2><ol><li>A transparent evidence and monitoring layer.</li><li>Risk pathways linking labour pressure to household harm.</li><li>Indicators, thresholds and human-reviewed triggers.</li><li>A catalogue of pre-agreed anticipatory-action activities and packages.</li><li>Cost and cost-of-inaction analysis.</li><li>Transition and resilience measures, including household Financial Runway.</li><li>Clear rules for escalation to broader income-protection approaches when shocks become systemic.</li><li>Country adaptations that preserve local institutions and definitions.</li></ol><h2>Canada is the first laboratory, not the whole project</h2><p>Canada is where the framework is being measured and challenged first. The aim is to learn whether the method works before adapting it to other advanced economies.</p><h2>Open research by design</h2><p>Sources, data definitions, failed tests, uncertainty, code, assumptions and research decisions remain visible. A finding without provenance is not considered publishable evidence.</p><p><a href="/framework">Core framework</a> · <a href="/countries/CA">Canada Lab</a> · <a href="/roadmap">Roadmap</a></p>')],
  '/roadmap': ['Roadmap',()=>intro('Roadmap','Build the humanitarian-to-socioeconomic framework, test it in Canada, define action packages and costs, then adapt it carefully across advanced economies.')+prose('<h2>Stage 1 · Core anticipatory-action framework - complete</h2><p>Define the humanitarian lineage, shock pathway, vulnerability logic, protection gap, transition window and action-package structure. Make migration status a research dimension rather than a vulnerability label.</p><h2>Stage 2 · Canada proof of concept - complete</h2><p>Test whether the quantitative architecture can separate artificial-intelligence exposure, labour pressure, population exposure, household fragility, policy protection and transition timing. The architecture survives; the current broad structural displacement alarm did not trigger.</p><h2>Stage 3 · Canada Quantitative Engine v1.0 - current</h2><p>Ingest the full population-by-occupation matrix, build Financial Runway, estimate sustainable transition time, encode policy eligibility and take-up, and run historical backtests.</p><h2>Stage 4 · Anticipatory Action Activity Catalogue</h2><p>Define candidate activities across readiness, early pressure, likely phase-out, imminent displacement and transition/recovery. Each activity gets a trigger, target group, delivery mechanism, duration, cost, evidence, risks and exit condition.</p><h2>Stage 5 · Cost and resilience model</h2><p>Compare the expected cost of anticipatory packages with delayed response, including benefits, housing distress, lost tax revenue and other social costs. Test when targeted support stops being sufficient and broader income guarantees deserve analysis.</p><h2>Stage 6 · Trigger and decision layer</h2><p>Only after evidence and actions are credible: test signal combinations, thresholds, human-review rules, escalation logic and stop rules. No statistical relationship automatically activates assistance.</p><h2>Stage 7 · Multi-country adaptation</h2><p>Adapt the framework for the European Union, United States, Australia, Gulf economies and other advanced labour markets. Each country keeps local definitions, social-protection institutions, vulnerable-population profiles and action logic.</p><h2>What will not be rushed</h2><p>There will be no universal artificial-intelligence disruption score, cross-country vulnerability ranking, automated trigger or universal-basic-income recommendation without evidence supporting it.</p>')],
  '/changelog':['Changelog',()=>intro('Changelog','Changes to the platform and its research records.')+prose('<h2>0.5.0 · 27 September 2026</h2><ul><li>Reframed the platform around its humanitarian anticipatory-action lineage and the extension of that logic to technological shocks in advanced economies.</li><li>Added a code-native framework pathway from technological hazard to exposure, household vulnerability, protection gap, trigger, action package and outcome.</li><li>Added a vulnerability/resilience matrix that includes refugees, asylum seekers, migrants and economically vulnerable citizens without treating migration status as a vulnerability score.</li><li>Added transition-gap, cost-of-action versus cost-of-delay and phased anticipatory-action package visuals.</li><li>Rebuilt the Early Warning, Actions, Why This Matters, Project and Roadmap pages around triggers, resilience, cost, job phase-out, transitions and broader income-protection scenarios.</li></ul><h2>0.4.1 · 26 September 2026</h2><ul><li>Added a public glossary and a site-wide plain-language rule: full names first, abbreviations second.</li><li>Rewrote the Canada Lab and computational proof-of-concept pages so the five model names and key measures are explained before shorthand is used.</li><li>Added automatic definitions for recognised abbreviations and a terminology section on every research-record page.</li><li>Added tests and live checks to keep the glossary and terminology explanations from disappearing in later releases.</li></ul><h2>0.4.0 · 26 September 2026</h2><ul><li>Restored the Canada computational POC v0.1 and v0.2 validation work from the project notebooks into the public research record.</li><li>Added the five-layer OTPM → PEXM → VACM → PBGM → TVPM architecture, validation results, negative control, population heterogeneity analysis, Financial Runway source stack, policy-gap mapping and transition-time sensitivity tests.</li><li>Added 31 structured research records covering sources, datasets, indicators, models, experiments and candidate actions.</li><li>Published the current POC verdict: architecture retained; broad structural AI-displacement alarm not triggered; calibration not production-ready.</li><li>Made failures and downgrades explicit, including the withdrawn thin-slice NPR ranking, unvalidated liquid-runway estimate, open Work-Sharing shock-fit gap and uncalibrated TVPM thresholds.</li></ul><h2>0.3.0 · 26 September 2026</h2><ul><li>Catalogued five additional Canadian sources covering immigrant labour outcomes, occupation employment, detailed vacancies, AI exposure and observed generative-AI use.</li><li>Defined three planned Canadian datasets, three new indicators and a narrower predictive hypothesis focused on incremental warning value.</li><li>Implemented AA-EXP-CA-002 as a leakage-aware rolling-origin forecast comparison with automated tests.</li><li>Added a Canada data architecture page and explicitly documented the unresolved monthly HELC mapping gap.</li><li>Advanced the Canada Lab from scoping to evidence build without publishing any unrun research result.</li></ul><h2>0.2.0 · 26 September 2026</h2><ul><li>Made project history, software tests and public source code more visible.</li><li>Expanded the roadmap from Canada validation to planned EU, US and later country adaptations.</li><li>Added direct navigation to experiments so planned and future failed/null tests are easier to inspect.</li><li>Clarified that Canada is the methodology pilot, not a universal model.</li></ul><h2>0.1.0 · 26 September 2026</h2><ul><li>Initial public research skeleton with narrative, evidence catalog and Canada Lab.</li><li>Seven source and proposed research records with permanent IDs and version-specific links.</li><li>Early-warning concept and action proposal explicitly labelled inactive or unvalidated.</li><li>Methodology, history, roadmap, JSON exports and deployment configuration.</li></ul><p>The original 0.1 website release contained no ingested observations or executed research experiments. v0.4 restores the earlier Canada POC work while clearly separating POC validation from production-grade calibration.</p>')],
  '/countries':['Country labs',()=>intro('Country labs','Shared structure. Local evidence and definitions.')+countries.map(c=>row(`/countries/${c.code}`,`${c.name} · ${c.stage}`,c.description)).join('')]
};
